/**
 * Copy the version from package.json into src/version.ts.
 *
 * ★ WHY A GENERATED FILE RATHER THAN READING package.json AT RUNTIME. A Worker bundle
 *   has no package.json beside it — `import pkg from '../package.json'` either inlines
 *   the whole manifest into the bundle or fails to resolve, depending on the bundler.
 *   A generated one-line module is the only form that survives every consumer.
 *
 * ⛔ src/version.ts IS GENERATED. Never hand-edit it; changesets owns the number, this
 *   script owns the file. It runs from `bun run version` (the changesets bump) and again
 *   from prepublishOnly, so a manual publish cannot ship a stale literal.
 */
const pkg = await Bun.file(new URL('../package.json', import.meta.url)).json();
const target = new URL('../src/version.ts', import.meta.url);

const body = `// ⛔ GENERATED by scripts/sync-version.ts — do not edit. Source: package.json.
export const VERSION: string = '${pkg.version}';
`;

await Bun.write(target, body);
console.log(`version.ts -> ${pkg.version}`);
